/**
 * Options for {@link PluginMethods.googleTrends}.
 */
export interface GoogleTrendsOptions {
  /**
   * Where: empty = worldwide, an ISO-2 country ('US'), a region ('US-CA') or a US metro ('US-
   * CA-807').
   */
  geo?: string;
  /**
   * Time range: now 1-H, now 4-H, now 1-d, now 7-d, today 1-m, today 3-m, today 12-m, today 5-y,
   * all, or a custom 'YYYY-MM-DD YYYY-MM-DD' (hourly for the last 7 days: 'YYYY-MM-DDTHH YYYY-MM-
   * DDTHH'). API default: today 12-m.
   */
  timeframe?: string;
  /**
   * Google Trends category id (0 = all categories, e.g. 71 = Food & Drink, 5 = Computers &
   * Electronics). API default: 0.
   */
  category?: number;
  /**
   * Which Google search to measure: web, images, news, youtube, shopping. API default: web.
   */
  property?: string;
  /**
   * Language of labels (region names, topic titles), e.g. 'en-US', 'de', 'fr'. API default: en-US.
   */
  hl?: string;
  /**
   * Timezone offset in minutes that day/hour buckets align to (Trends' convention: 300 = UTC-5, -60
   * = UTC+1). Default 0 = UTC. API default: 0.
   */
  tz?: number;
  /**
   * Level of the interest-by-region map: country, region, city, dma. Default = Trends' own choice
   * (countries worldwide, regions in a country).
   */
  regionResolution?: string;
  /**
   * Include regions with low search volume in the region map. API default: false.
   */
  includeLowVolume?: boolean;
  /**
   * What to fetch: a comma list of interest_over_time, interest_by_region, related_queries,
   * related_topics, or 'all'. Fewer sections = faster. related_topics is opt-in (Google often
   * returns it empty). API default: interest_over_time,interest_by_region,related_queries.
   */
  sections?: string;
  /**
   * Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Optional - by default a country
   * outside the US and Europe is used; results follow `geo`, not the proxy country.
   */
  proxyCountry?: string;
}

