  /**
   * Scrape all reviews of an Airbnb listing.
   *
   * Given an Airbnb `room` (listing id or room URL), returns its guest `reviews`: `id`, `rating`,
   * `text` (as written) with its `language`, `translatedText` (Airbnb's translation into `locale`),
   * `date` (ISO), `localizedDate`, `stayDetail`, `photos`, `reviewer` (`id`, `name`, `photo`,
   * `location` or `tenure`, `profileUrl`, `profileId`, `isSuperhost`, `deleted`) and the host's
   * `response`. `reviewer.id` is Airbnb's account id (the one in its photo URLs;
   * airbnb.com/users/show/<id> asks anonymous visitors to log in), while `profileUrl` is the public
   * profile link Airbnb's own review cards open, keyed by a separate public id given as `profileId`.
   * `deleted` is true when the guest has since closed their Airbnb account; Airbnb still sends the
   * name, photo and location or tenure from the review, and they are returned as sent. Reads every
   * review, not just the few on the room page: page with `page` (or `offset`) and `max_reviews` (up
   * to 500 per call), order with `sort` (most_relevant, most_recent, highest_rated, lowest_rated)
   * and drop older reviews with `since`. Also returns the `listing` summary (title, overall and
   * category `rating`, `ratingDistribution`, `ratingCounts`, `reviewsCount`, `reviewTags`, host) and
   * `totalResults`, `hasMore`, `nextPage`, `nextOffset`. `ratingDistribution` is Airbnb's own list
   * of each star's share of the ratings as a 0-1 fraction (`{"stars": 5, "percentage": 0.957}` =
   * 95.7%), not a count like the other review plugins return; `ratingCounts` gives the number of
   * ratings per star (`{"5": 692, ...}`) worked out from those shares and `reviewsCount`, and is
   * null when the shares do not fit it (seen on hotel listings, whose distribution covers more
   * ratings than `reviewsCount`). Billed one unit per 50-review page read (`pagesFetched`).
   * Companion to the Airbnb search (`/travel/airbnb`) and listing (`/travel/airbnb-room`) plugins.
   * @param room Airbnb listing id (e.g. 23860926) or a room URL on any Airbnb domain, e.g.
   * 'https://www.airbnb.co.uk/rooms/23860926'.
   * Calls `POST /travel/airbnb-reviews`.
   */
  airbnbReviews(room: string, options: AirbnbReviewsOptions = {}): Promise<unknown> {
    return this.postJson("/travel/airbnb-reviews", {
      room: room,
      max_reviews: options.maxReviews,
      page: options.page,
      offset: options.offset,
      sort: options.sort,
      locale: options.locale,
      since: options.since,
      include_listing: options.includeListing,
      proxy_country: options.proxyCountry,
    });
  }

