  googleTrends(keywords: string | string[], options: GoogleTrendsOptions = {}): Promise<unknown> {
    return this.postJson("/trends/google-trends", {
      keywords: joined(keywords, ","),
      geo: options.geo,
      timeframe: options.timeframe,
      category: options.category,
      property: options.property,
      hl: options.hl,
      tz: options.tz,
      region_resolution: options.regionResolution,
      include_low_volume: options.includeLowVolume,
      sections: options.sections,
      proxy_country: options.proxyCountry,
    });
  }

